export const EVALUATING_SOLUTIONS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Mengapa mengevaluasi",q:"Setelah menjalankan sebuah solusi, mengapa penting mengevaluasinya?",options:["Untuk mengetahui apakah masalahnya benar-benar teratasi, atau perlu diperbaiki/diganti","Evaluasi hanya membuang waktu, karena solusi yang sudah dijalankan pasti sudah berhasil dengan sendirinya","Supaya kelompok terlihat sibuk dan rajin di depan guru, walaupun hasil evaluasinya tidak pernah dipakai"],answer:0,explain:"Tanpa evaluasi, kita tidak tahu apakah usaha kita berhasil atau justru perlu diubah.",hint:"Bagaimana kamu tahu solusinya bekerja tanpa memeriksanya?"},
{n:2,type:"mcq",micro:"Mengevaluasi terhadap tujuan",q:"Cara paling langsung mengevaluasi solusi adalah membandingkan hasilnya dengan...",options:["Perasaan hari itu","Tujuan dan kriteria keberhasilan yang ditetapkan di awal","Solusi orang lain"],answer:1,explain:"Kriteria yang dibuat sebelum melaksanakan menjadi tolok ukur: apakah hasilnya memenuhi kriteria itu?",hint:"Apa yang kamu tetapkan sebagai 'tanda berhasil' sebelum mulai?"},
{n:3,type:"mcq",micro:"Bukti, bukan kesan",q:"Untuk menilai apakah 'sistem antre baru' berhasil, bukti yang paling berguna:",options:["Perasaan bahwa 'sepertinya antrean menjadi lebih baik' yang dimiliki oleh pembuat sistem itu sendiri","Pendapat satu orang yang kebetulan lewat di dekat kantin sekali saja pada hari pertama sistem dicoba","Waktu antre rata-rata sebelum dan sesudah, dari pengukuran nyata"],answer:2,explain:"Data yang dikumpulkan dengan cara yang sama sebelum dan sesudah memberi penilaian yang lebih dapat dipercaya daripada kesan.",hint:"Angka apa yang bisa kamu bandingkan 'sebelum' dan 'sesudah'?"},
{n:4,type:"mcq",micro:"Keadaan awal (baseline)",q:"'Baseline' adalah...",options:["Ukuran keadaan SEBELUM solusi diterapkan, sebagai pembanding","Garis di lapangan","Nama solusinya"],answer:0,explain:"Tanpa mencatat keadaan awal, sulit membuktikan solusi menyebabkan perubahan.",hint:"Kamu perlu tahu 'dari mana' untuk mengukur 'seberapa jauh'."},
{n:5,type:"tf",micro:"Beri waktu sebelum menilai",q:"Benar atau Salah: Solusi yang mengubah kebiasaan biasanya perlu diberi waktu beberapa hari atau minggu sebelum dievaluasi dengan adil.",answer:true,explain:"Menilai terlalu cepat bisa menangkap 'kekacauan masa transisi', bukan hasil sebenarnya. Beri waktu penyesuaian.",hint:"Apakah kebiasaan baru langsung berjalan mulus di hari pertama?"},
{n:6,type:"mcq",micro:"Menguji dulu",q:"Menguji solusi di lingkup kecil (satu kelas, satu minggu) sebelum menerapkannya luas berguna karena...",options:["Membuang sumber daya dan waktu karena hasil uji di satu kelas pasti tidak bisa dipakai untuk kelas lain","Masalah bisa ditemukan dengan risiko kecil dan solusi diperbaiki sebelum skala penuh","Uji kecil tidak berarti apa-apa, sebab masalah yang sebenarnya baru muncul kalau solusinya langsung dipakai luas"],answer:1,explain:"Uji coba (pilot) adalah bentuk evaluasi awal yang murah.",hint:"Lebih baik menemukan cacat di 1 kelas atau 20 kelas?"},
{n:7,type:"mcq",micro:"Tanda solusi berhasil",q:"Solusi 'papan pengingat piket' bisa disebut berhasil kalau...",options:["Papannya terlihat bagus, berwarna cerah, dan dipasang di tempat yang mudah dilihat oleh semua anggota kelas","Semua orang tahu papan itu ada di dinding kelas, walaupun jumlah hari piket yang terlewat tidak berubah","Jumlah hari piket terlewat berkurang jelas dibanding sebelumnya"],answer:2,explain:"Keberhasilan diukur dari perubahan pada masalah aslinya (piket terlewat), bukan dari keberadaan solusi.",hint:"Apa masalah aslinya, dan apakah masalah itu berkurang?"},
{n:8,type:"order",micro:"Langkah mengevaluasi solusi",q:"Urutkan langkah mengevaluasi sebuah solusi.",items:["Ingat kembali tujuan & kriteria keberhasilan, dan keadaan awal (baseline)","Kumpulkan data/bukti tentang keadaan setelah solusi berjalan","Bandingkan: apakah kriteria terpenuhi? Seberapa besar perubahannya?","Simpulkan: lanjutkan, perbaiki, atau ganti solusi"],answer:[0,1,2,3],explain:"Ingat target & baseline → kumpulkan data sesudah → bandingkan → putuskan langkah berikutnya.",hint:"Kamu perlu tahu target sebelum bisa menilai."},
{n:9,type:"mcq",micro:"Solusi berhasil sebagian",q:"Solusi mengurangi masalah dari '15 kejadian per minggu' menjadi '6 per minggu'. Ini...",options:["Kemajuan nyata, meski belum sempurna — bisa dilanjutkan sambil dicari perbaikan tambahan","Kegagalan total karena masalahnya belum mencapai nol, sehingga usaha yang sudah dilakukan dianggap tidak ada artinya","Berarti solusi itu harus dibuang seluruhnya, karena solusi yang baik harus langsung menghilangkan semua kejadian"],answer:0,explain:"Evaluasi tidak selalu 'berhasil / gagal'. Perbaikan sebagian tetap berharga dan bisa dibangun lebih lanjut.",hint:"Apakah turun dari 15 ke 6 tidak berarti apa-apa?"},
{n:10,type:"mcq",micro:"Solusi gagal",q:"Setelah dievaluasi jujur, solusi ternyata tidak mengubah masalah sama sekali. Sikap yang produktif:",options:["Menyerah pada masalahnya","Catat apa yang tidak berhasil dan mengapa, lalu coba kandidat solusi berikutnya","Pura-pura berhasil"],answer:1,explain:"Solusi yang gagal memberi informasi. 'Sekarang kita tahu X tidak jalan karena Y' menyempit pilihan berikutnya.",hint:"Apa yang bisa kamu pelajari dari kegagalan ini?"},
{n:11,type:"mcq",micro:"Efek samping",q:"Saat mengevaluasi, selain 'apakah masalah utama teratasi', juga perlu ditanya...",options:["Apakah solusinya terlihat modern dan keren sehingga orang lain kagum ketika melihat cara kelompok bekerja","Siapa yang pertama kali mengusulkannya, supaya kelompok tahu siapa yang pantas mendapat pujian paling besar","Apakah solusi ini menimbulkan masalah baru atau mengganggu pihak lain"],answer:2,explain:"Solusi bisa menyelesaikan satu hal tapi merusak yang lain. Evaluasi lengkap memeriksa efek samping.",hint:"Apa lagi yang berubah sejak solusi ini dijalankan?"},
{n:12,type:"tf",micro:"Evaluasi butuh kejujuran",q:"Benar atau Salah: Orang cenderung menilai solusi yang mereka usulkan sendiri secara lebih ketat dan lebih pesimis daripada kenyataannya.",answer:false,explain:"Justru sebaliknya: keterikatan pada ide sendiri membuat kita melihatnya lebih berhasil dari kenyataannya. Meminta orang lain menilai, atau memakai data, membantu jujur.",hint:"Apakah mudah mengakui bahwa ide sendiri tidak berhasil?"},
{n:13,type:"mcq",micro:"Menanyakan pengguna",q:"Cara mengevaluasi solusi 'rak sepatu baru' selain mengamati:",options:["Bertanya ke siswa yang memakainya: lebih mudah menemukan sepatu? Ada kendala?","Menanyakannya kepada kepala sekolah saja, karena hanya beliau yang tahu apakah rak itu bermanfaat bagi siswa","Tidak bertanya kepada siapa pun, sebab pengamatan sendiri sudah cukup untuk menilai semua sisi solusinya"],answer:0,explain:"Orang yang terdampak solusi punya informasi tentang apa yang bekerja dan apa yang mengganggu.",hint:"Siapa yang paling tahu apakah rak itu membantu?"},
{n:14,type:"mcq",micro:"Ukuran yang cocok",q:"Untuk solusi 'kurangi kebisingan kelas', ukuran evaluasi yang paling langsung:",options:["Warna dinding","Berapa kali guru harus meminta diam per pelajaran, atau tingkat kebisingan yang diamati","Jumlah siswa di kelas"],answer:1,explain:"Pilih ukuran yang benar-benar mencerminkan masalah yang ingin dikurangi.",hint:"Apa tanda konkret bahwa kelas lebih tenang?"},
{n:15,type:"mcq",micro:"Membandingkan dengan tanpa solusi",q:"Kalau memungkinkan, membandingkan kelas yang memakai solusi dengan kelas serupa yang tidak, berguna karena...",options:["Membuat evaluasi tidak adil","Tidak berguna","Membantu memisahkan efek solusi dari perubahan lain yang terjadi pada semua kelas (misalnya musim ujian)"],answer:2,explain:"Kelompok pembanding membantu memastikan perubahan disebabkan solusi, bukan faktor lain.",hint:"Bagaimana kamu tahu perbaikan bukan karena hal lain yang berubah untuk semua orang?"},
{n:16,type:"mcq",micro:"Evaluasi cepat vs mendalam",q:"Untuk solusi kecil berisiko rendah, evaluasi yang sesuai:",options:["Pengamatan cepat beberapa hari: 'apakah ini membantu?' — tidak perlu pengukuran rumit","Studi enam bulan","Tidak perlu evaluasi sama sekali"],answer:0,explain:"Besar evaluasi sebaiknya sepadan dengan besar dan pentingnya solusi.",hint:"Apakah memindahkan tempat sampah butuh laporan penelitian?"},
{n:17,type:"tf",micro:"Refleksi tentang proses",q:"Benar atau Salah: Refleksi sebaiknya hanya membahas hasil akhir; membahas PROSES (apa yang lancar, apa yang menyulitkan) tidak memberi manfaat.",answer:false,explain:"Merefleksikan proses justru memperbaiki cara kita memecahkan masalah berikutnya, terlepas dari hasil kali ini.",hint:"Apa yang bisa kamu lakukan lebih baik lain kali?"},
{n:18,type:"mcq",micro:"Mencatat pelajaran",q:"Di akhir, menuliskan '3 hal yang kami pelajari' berguna karena...",options:["Hanya untuk arsip","Pelajaran mudah terlupa; catatan membuatnya tersedia untuk masalah dan tim berikutnya","Menambah pekerjaan tanpa manfaat"],answer:1,explain:"Pelajaran yang dicatat adalah 'tabungan pengetahuan' yang bisa dipakai lagi.",hint:"Bagaimana tim berikutnya menghindari kesalahan yang sama?"},
{n:19,type:"mcq",micro:"Kapan berhenti",q:"Solusi dievaluasi dan masalah teratasi memenuhi kriteria. Langkah yang tepat:",options:["Terus mengutak-atik solusi tanpa henti walaupun masalahnya sudah teratasi dan semua kriteria sudah terpenuhi","Langsung melupakan semuanya tanpa mencatat apa pun, sehingga solusi bisa hilang begitu pelaksananya pergi","Tutup dengan rapi: dokumentasikan, pastikan solusi bisa berjalan sendiri, ucapkan terima kasih"],answer:2,explain:"Penutupan yang baik memastikan hasil bertahan dan pelajaran tersimpan.",hint:"Apa yang membedakan masalah yang 'ditinggalkan' dari yang 'diselesaikan'?"},
{n:20,type:"open",micro:"Merancang evaluasi sederhana",q:"Kamu menerapkan solusi 'kotak saran anonim di kelas' untuk masalah 'siswa segan menyampaikan keluhan'. Rancang cara mengevaluasinya: ukuran apa, data 'sebelum', kapan dinilai, dan apa tanda berhasil.",explain:"Jawaban baik menyebut ukuran yang relevan, data pembanding, jeda waktu yang wajar, dan kriteria berhasil yang konkret.",hint:"Apa angka yang bisa kamu hitung sebelum dan sesudah?",sample:"Ukuran: jumlah saran/keluhan yang masuk per minggu, dan berapa yang bisa ditindaklanjuti. Data 'sebelum': catat berapa keluhan disampaikan secara terbuka dalam sebulan terakhir (perkiraan, misal 2). Kapan dinilai: setelah 4 minggu (beri waktu siswa terbiasa). Tanda berhasil: minimal 6 saran masuk dalam 4 minggu, mencakup isu yang sebelumnya tidak pernah terdengar, dan tidak ada penyalahgunaan berarti (saran kasar/mengejek). Tambahan: tanya 5 siswa acak apakah mereka merasa lebih nyaman menyampaikan pendapat."},
{n:21,type:"mcq",micro:"Perubahan karena solusi atau kebetulan",q:"Setelah solusi 'pengingat PR' diterapkan, nilai kelas naik. Sebelum menyimpulkan solusi berhasil, periksa...",options:["Apakah ada hal lain yang berubah bersamaan (topik lebih mudah, guru mengubah cara mengajar, mendekati ujian jadi semua lebih rajin)","Tidak perlu memeriksa apa pun lagi, karena nilai yang naik setelah solusi berjalan pasti berasal dari solusi itu","Langsung umumkan keberhasilan kepada seluruh sekolah, karena nilai naik adalah bukti paling kuat bahwa solusi berhasil"],answer:0,explain:"Perubahan yang terjadi bersamaan dengan solusi belum tentu disebabkan solusi. Cari penjelasan alternatif.",hint:"Apa lagi yang berbeda pada periode itu?"},
{n:22,type:"mcq",micro:"Ukuran yang menyesatkan",q:"Solusi dinilai berhasil karena 'jumlah sampah di tempat sampah naik'. Tapi ternyata siswa membuang sampah kelas lain ke sana. Pelajaran:",options:["Berarti solusinya sudah sempurna, karena angka yang naik selalu menandakan bahwa tujuan solusi benar-benar tercapai","Pilih ukuran yang tidak mudah 'dipenuhi' dengan cara yang tidak diinginkan; periksa apakah angka naik untuk alasan yang benar","Ukuran tidak pernah menyesatkan, sehingga angka yang naik harus selalu dipercaya tanpa perlu diperiksa alasannya"],answer:1,explain:"Ukuran yang buruk bisa menunjukkan 'berhasil' padahal masalah aslinya tidak berkurang. Periksa maknanya.",hint:"Apakah angka yang naik itu berarti hal yang kita inginkan benar-benar terjadi?"},
{n:23,type:"mcq",micro:"Iterasi",q:"'Iterasi' dalam pemecahan masalah berarti...",options:["Menyerah setelah percobaan yang pertama kalau hasilnya belum bagus, lalu mencari masalah yang baru lainnya","Mengerjakan hal yang sama berulang-ulang tanpa perubahan apa pun, dengan harapan hasilnya akan berbeda nantinya","Mengulang siklus: coba → evaluasi → perbaiki → coba lagi, sampai cukup baik"],answer:2,explain:"Solusi jarang sempurna di percobaan pertama. Iterasi memperbaikinya bertahap berdasarkan hasil nyata.",hint:"Apa yang kamu lakukan setelah evaluasi menunjukkan 'lumayan tapi belum cukup'?"},
{n:24,type:"mcq",micro:"Perbaikan kecil vs ganti total",q:"Evaluasi menunjukkan solusi 'hampir berhasil, kecuali satu bagian macet'. Respons yang biasanya tepat:",options:["Perbaiki bagian yang macet, pertahankan sisanya — bukan membuang seluruh solusi","Buang seluruh solusi dan mulai dari nol lagi, walaupun sebagian besar bagiannya sudah berjalan dengan baik","Abaikan saja bagian yang macet dan anggap solusinya sudah selesai, karena sebagian besar sudah berhasil dijalankan"],answer:0,explain:"Kalau sebagian besar berjalan, memperbaiki titik lemah lebih efisien daripada mengganti semuanya.",hint:"Apakah kamu membuang seluruh sepeda karena satu ban kempes?"},
{n:25,type:"classify",micro:"Hasil evaluasi dan tindakan",q:"Kelompokkan hasil evaluasi dengan tindakan yang tepat: 'Lanjutkan', 'Perbaiki', atau 'Ganti solusi'.",items:["Kriteria terpenuhi, tidak ada efek samping berarti","Sebagian besar berhasil, satu bagian menimbulkan keluhan kecil","Tidak ada perubahan pada masalah setelah waktu yang cukup","Masalah utama berkurang tapi muncul masalah baru yang lebih besar"],groups:["Lanjutkan","Perbaiki","Ganti solusi"],answer:{"Lanjutkan":["Kriteria terpenuhi, tidak ada efek samping berarti"],"Perbaiki":["Sebagian besar berhasil, satu bagian menimbulkan keluhan kecil"],"Ganti solusi":["Tidak ada perubahan pada masalah setelah waktu yang cukup","Masalah utama berkurang tapi muncul masalah baru yang lebih besar"]},explain:"Berhasil bersih → lanjutkan; berhasil sebagian → perbaiki; tidak berhasil atau merugikan → ganti.",hint:"Seberapa jauh hasil dari yang diharapkan, dan apakah ada kerugian baru?"},
{n:26,type:"mcq",micro:"Evaluasi jangka pendek vs panjang",q:"Solusi 'hadiah untuk kelas terbersih' berhasil di bulan pertama lalu memudar. Evaluasi jangka panjang mengungkap...",options:["Bulan pertama adalah satu-satunya bulan yang penting, jadi hasil bulan-bulan berikutnya tidak perlu dilihat lagi","Efek yang bergantung pada hadiah cenderung hilang saat hadiah berhenti; perlu solusi yang membangun kebiasaan","Solusi yang berhasil sekali akan selalu berhasil seterusnya, sehingga evaluasi jangka panjang tidak diperlukan"],answer:1,explain:"Beberapa solusi bekerja di awal lalu melemah. Evaluasi berkelanjutan menangkap pola ini.",hint:"Apa yang terjadi setelah 'kebaruan' solusi hilang?"},
{n:27,type:"mcq",micro:"Data kualitatif",q:"Selain angka, komentar seperti 'aku tidak tahu cara pakai sistem barunya' berguna karena...",options:["Komentar tidak pernah berguna dalam evaluasi, karena komentar hanyalah pendapat dan tidak bisa dipakai memperbaiki","Hanya angka yang penting dalam evaluasi, sehingga komentar dari pengguna sebaiknya langsung diabaikan saja","Menjelaskan MENGAPA angka bergerak (atau tidak) dan menunjuk perbaikan yang spesifik"],answer:2,explain:"Angka menunjukkan APA yang terjadi; komentar sering menjelaskan MENGAPA dan bagaimana memperbaikinya.",hint:"Kalau angkanya tidak bergerak, komentar bisa memberitahumu penyebabnya."},
{n:28,type:"mcq",micro:"Sampel evaluasi",q:"Menilai solusi hanya dengan bertanya ke 2 teman dekat yang membantu membuatnya berisiko...",options:["Pendapat mereka bisa terlalu positif; tanya juga orang yang tidak terlibat dan yang skeptis","Dua orang selalu cukup untuk menilai solusi, walaupun keduanya adalah orang yang paling dekat dengan pembuatnya","Teman dekat adalah penilai yang paling objektif, karena mereka paling mengenal pembuat solusi dan niat baiknya"],answer:0,explain:"Sumber evaluasi yang bias (terlibat, mendukung) memberi gambaran yang terlalu cerah.",hint:"Siapa yang mungkin memberi pendapat jujur yang tidak enak didengar?"},
{n:29,type:"tf",micro:"Kegagalan cepat lebih baik",q:"Benar atau Salah: Lebih baik menemukan bahwa sebuah solusi tidak berhasil setelah diterapkan luas daripada menemukannya lebih awal lewat uji coba kecil.",answer:false,explain:"Sebaliknya. Kegagalan yang ditemukan awal (lewat uji kecil) murah dan bisa diperbaiki; kegagalan yang ditemukan setelah komitmen besar jauh lebih mahal.",hint:"Kapan lebih murah menemukan cacat: di prototipe atau di produk jadi 1.000 unit?"},
{n:30,type:"order",micro:"Siklus iterasi",q:"Urutkan langkah satu putaran iterasi perbaikan solusi.",items:["Jalankan solusi (atau versi perbaikannya) untuk periode tertentu","Kumpulkan data & umpan balik tentang hasil dan kendala","Identifikasi satu atau dua perbaikan yang paling berdampak","Terapkan perbaikan itu, lalu ulangi siklus"],answer:[0,1,2,3],explain:"Jalankan → kumpulkan hasil → pilih perbaikan → terapkan & ulangi.",hint:"Kamu butuh hasil untuk tahu apa yang perlu diperbaiki."},
{n:31,type:"mcq",micro:"Membandingkan sebelum-sesudah dengan adil",q:"Agar perbandingan 'sebelum vs sesudah' adil, pengukurannya sebaiknya...",options:["Hanya diukur sesudah solusi dijalankan saja, karena keadaan sebelumnya sudah tidak mungkin diukur dengan benar","Dilakukan dengan cara, alat, dan pada kondisi yang sama (misalnya hari & jam yang sebanding)","Diukur dengan cara yang berbeda setiap kali supaya hasilnya terlihat lebih bervariasi dan lebih lengkap"],answer:1,explain:"Perubahan cara mengukur bisa menciptakan 'perbaikan' palsu atau menyembunyikan perbaikan nyata.",hint:"Kalau kamu mengukur antre siang hari sebelumnya dan pagi hari sesudahnya, apakah adil?"},
{n:32,type:"mcq",micro:"Evaluasi menemukan masalah baru",q:"Evaluasi solusi 'jalur masuk satu arah' menunjukkan koridor lancar TAPI pintu belakang jadi macet. Ini berarti...",options:["Solusi itu sudah sempurna, karena koridor lancar adalah satu-satunya tempat yang perlu diperhatikan sekolah","Pintu belakang tidak penting untuk dinilai, sebab semua siswa pasti bisa menunggu lebih lama di tempat itu","Solusi memindahkan sebagian masalah; perlu penyesuaian yang memperhitungkan seluruh alur, bukan hanya koridor depan"],answer:2,explain:"Evaluasi yang teliti melihat seluruh sistem, bukan hanya bagian yang ditargetkan.",hint:"Apakah masalahnya hilang, atau pindah tempat?"},
{n:33,type:"mcq",micro:"Menetapkan ambang 'cukup baik'",q:"Sebelum evaluasi, menyepakati 'seberapa baik dianggap cukup' (misalnya 'antre di bawah 5 menit') berguna karena...",options:["Menghindari perdebatan tak berujung tentang apakah hasilnya 'berhasil' — ada garis yang jelas","Membuat evaluasi menjadi lebih sulit dan rumit, sehingga hasil penilaian tidak bisa dipakai untuk menilai solusi","Ambang batas tidak pernah membantu, karena keberhasilan hanya bisa dilihat dari perasaan orang saat itu juga"],answer:0,explain:"Ambang yang disepakati di awal membuat kesimpulan evaluasi objektif dan cepat.",hint:"Bagaimana kalian sepakat bahwa hasilnya 'cukup baik'?"},
{n:34,type:"mcq",micro:"Umpan balik yang bertentangan",q:"Sebagian siswa bilang solusi baru 'membantu', sebagian bilang 'mengganggu'. Langkah yang tepat:",options:["Batalkan solusi itu sekarang juga, karena solusi yang baik harus disukai oleh semua siswa tanpa terkecuali","Cari tahu apakah kedua kelompok punya kebutuhan berbeda, dan apakah solusi bisa disesuaikan untuk keduanya","Abaikan saja siswa yang mengeluh, karena yang berkata solusi membantu pasti lebih benar daripada mereka"],answer:1,explain:"Umpan balik yang terbelah sering menunjuk ke kelompok dengan kebutuhan berbeda. Solusi mungkin perlu opsi atau penyesuaian.",hint:"Mengapa satu kelompok terbantu dan yang lain terganggu?"},
{n:35,type:"mcq",micro:"Overreaksi terhadap satu keluhan",q:"Satu orang mengeluh keras tentang solusi yang menurut data membantu 90% orang. Respons berimbang:",options:["Batalkan solusi","Abaikan total keluhannya","Dengarkan keluhannya, lihat apakah bisa diakomodasi tanpa merusak manfaat bagi mayoritas — bukan langsung membatalkan solusi"],answer:2,explain:"Satu suara keras tidak boleh otomatis mengalahkan bukti manfaat luas, tapi juga tidak boleh diabaikan begitu saja.",hint:"Bagaimana menyeimbangkan satu keberatan dengan manfaat untuk banyak orang?"},
{n:36,type:"mcq",micro:"Evaluasi tanpa target jelas",q:"Kalau di awal tidak ada kriteria keberhasilan, evaluasi menjadi sulit karena...",options:["Tidak ada garis untuk menilai 'berhasil atau tidak' — orang akan berdebat berdasarkan perasaan","Evaluasi jadi lebih mudah","Tidak masalah"],answer:0,explain:"Ini alasan menetapkan kriteria SEBELUM melaksanakan. Kalau terlanjur tidak ada, sepakati sekarang sebelum menilai.",hint:"Tanpa target, bagaimana dua orang bisa sepakat apakah hasilnya baik?"},
{n:37,type:"tf",micro:"Refleksi jujur butuh keamanan",q:"Benar atau Salah: Tim lebih bisa merefleksikan kesalahan secara jujur kalau suasananya aman — fokus pada 'apa yang bisa diperbaiki', bukan mencari siapa yang salah.",answer:true,explain:"Ketika orang takut disalahkan, mereka menyembunyikan masalah. Refleksi yang berfokus perbaikan menghasilkan pelajaran nyata.",hint:"Apakah orang berbagi kesalahan lebih bebas saat merasa aman atau saat takut dihukum?"},
{n:38,type:"mcq",micro:"Menyimpan solusi lama sebagai cadangan",q:"Saat mengganti solusi yang gagal dengan yang baru, berguna...",options:["Menyalahkan orang yang mengusulkan solusi lama agar ia tidak berani mengusulkan ide lagi di lain waktu","Mencatat mengapa yang lama gagal, agar tidak diulang, dan menyimpan kandidat lain yang belum dicoba","Menghapus semua jejak solusi yang lama supaya tidak ada yang mengingat kegagalan yang pernah terjadi"],answer:1,explain:"Evaluasi kegagalan mengubahnya menjadi peta: 'jangan ke sini, karena...'.",hint:"Apa yang membantu percobaan berikutnya lebih baik?"},
{n:39,type:"mcq",micro:"Evaluasi berkelanjutan",q:"Untuk solusi yang berjalan lama (sistem piket permanen), evaluasi sebaiknya...",options:["Sekali saja di awal","Tidak pernah","Dilakukan berkala (misalnya tiap bulan/semester), karena keadaan dan kebutuhan berubah"],answer:2,explain:"Solusi permanen bisa menjadi usang. Peninjauan berkala menjaganya tetap sesuai.",hint:"Apakah solusi yang cocok tahun lalu pasti masih cocok tahun ini?"},
{n:40,type:"open",micro:"Menganalisis hasil evaluasi",q:"Solusi: 'jadwal buka jendela + pindah lemari' untuk kelas pengap. Setelah 2 minggu: pagi terasa lebih segar (5 dari 6 siswa yang ditanya setuju), tapi siang tetap panas, dan satu siswa alergi debu terganggu saat jendela dibuka lebar. Tuliskan kesimpulan evaluasi (lanjut/perbaiki/ganti) dengan alasan, dan 2 penyesuaian.",explain:"Jawaban baik: memilih 'perbaiki' dengan alasan (berhasil sebagian, kelemahan spesifik), dan penyesuaian yang menyasar tiap kelemahan.",hint:"Berhasil sebagian + kelemahan yang bisa ditangani = perbaiki, bukan ganti.",sample:"Kesimpulan: PERBAIKI. Solusi berhasil sebagian (pagi lebih baik, mayoritas setuju) sehingga tidak perlu diganti, tapi dua kelemahan nyata (siang panas, satu siswa terganggu debu). Penyesuaian: (1) untuk siang, tambahkan kipas kecil atau atur agar tirai/jendela sisi matahari ditutup saat siang sambil sisi lain tetap terbuka untuk aliran udara; (2) untuk siswa alergi, pindahkan tempat duduknya menjauh dari jendela yang dibuka lebar, dan pastikan area dibersihkan dari debu secara rutin; buka jendela lebar hanya sebelum siswa masuk agar debu awal mengendap."},
{n:41,type:"mcq",micro:"Evaluasi formatif vs sumatif",q:"Evaluasi 'formatif' (selama solusi berjalan, untuk memperbaiki) berbeda dari 'sumatif' (di akhir, untuk menilai keberhasilan keseluruhan). Keduanya berguna karena...",options:["Formatif membantu menyesuaikan sambil jalan; sumatif memberi penilaian akhir dan pelajaran untuk lain kali","Hanya evaluasi sumatif yang penting, karena menilai sambil jalan hanya mengganggu orang yang sedang bekerja","Evaluasi formatif membuang waktu, sebab perbaikan sebaiknya hanya dilakukan setelah semuanya benar-benar selesai"],answer:0,explain:"Evaluasi bukan hanya kegiatan akhir. Pengecekan berkala selama pelaksanaan memungkinkan perbaikan tepat waktu.",hint:"Kapan lebih baik tahu ada masalah: di tengah jalan atau setelah semuanya selesai?"},
{n:42,type:"mcq",micro:"Retrospektif terstruktur",q:"Format refleksi tim yang umum: 'Apa yang berjalan baik? Apa yang tidak? Apa yang akan kita ubah?' Kegunaan format ini:",options:["Hanya untuk formalitas agar terlihat resmi, padahal isinya tidak pernah dipakai untuk mengubah cara kerja tim","Memastikan tim membahas keberhasilan DAN kesulitan DAN tindakan perbaikan, bukan hanya mengeluh atau hanya memuji","Membuat rapat menjadi lebih lama tanpa hasil, karena tiga pertanyaan itu sudah selalu dijawab sama setiap kali"],answer:1,explain:"Struktur menjaga refleksi seimbang dan berujung pada tindakan konkret.",hint:"Apa tiga hal yang harus dibahas agar refleksi menghasilkan perbaikan?"},
{n:43,type:"mcq",micro:"Akar dari hasil yang mengecewakan",q:"Solusi gagal. Sebelum menyimpulkan 'idenya buruk', periksa juga...",options:["Tidak perlu periksa apa pun","Langsung ganti ide","Apakah pelaksanaannya sesuai rencana — solusi bagus yang dijalankan setengah hati juga akan gagal"],answer:2,explain:"Kegagalan bisa karena ide yang salah ATAU pelaksanaan yang buruk. Membedakannya penting agar tidak membuang ide yang sebenarnya baik.",hint:"Apakah solusinya benar-benar dijalankan seperti yang direncanakan?"},
{n:44,type:"mcq",micro:"Menghitung dampak bersih",q:"Solusi menghemat 10 menit antre tapi menambah 3 menit untuk mengambil nomor. Dampak bersihnya...",options:["Hemat 7 menit — evaluasi harus menghitung biaya baru yang ditimbulkan solusi, bukan hanya manfaatnya","Hemat 10 menit","Rugi 3 menit"],answer:0,explain:"Evaluasi jujur mengurangi biaya/kerepotan baru dari manfaat kotor untuk mendapat manfaat bersih.",hint:"Manfaat dikurangi biaya baru = ?"},
{n:45,type:"mcq",micro:"Bukti yang cukup",q:"Berapa banyak bukti yang dibutuhkan sebelum menyimpulkan solusi berhasil bergantung pada...",options:["Tidak butuh bukti","Besarnya taruhan keputusan — solusi kecil reversibel butuh sedikit bukti; solusi besar sulit dibatalkan butuh lebih banyak","Selalu butuh bukti yang sama banyak"],answer:1,explain:"Sesuaikan usaha pengumpulan bukti dengan pentingnya dan reversibilitas keputusan.",hint:"Apakah memutuskan tata letak kursi butuh bukti sebanyak memutuskan mengubah kurikulum?"},
{n:46,type:"order",micro:"Retrospektif proyek",q:"Urutkan langkah melakukan retrospektif setelah proyek selesai.",items:["Kumpulkan fakta: hasil vs target, garis waktu vs rencana, kejadian penting","Bahas: apa yang berjalan baik, apa yang menyulitkan, dan mengapa","Sepakati 2–3 perubahan konkret untuk lain kali","Catat pelajaran di tempat yang bisa ditemukan tim berikutnya"],answer:[0,1,2,3],explain:"Fakta dulu → analisis → tindakan perbaikan → simpan pelajaran.",hint:"Mulai dari fakta agar diskusi tidak sekadar perasaan."},
{n:47,type:"mcq",micro:"Perbedaan 'tidak berhasil' dan 'belum cukup waktu'",q:"Solusi kebiasaan baru dievaluasi setelah 3 hari dan disebut gagal. Kritik yang wajar:",options:["Tiga hari lebih dari cukup untuk menilai kebiasaan baru, karena kebiasaan yang bagus langsung terlihat hasilnya","Evaluasi tidak pernah terlalu dini, sebab semakin cepat dinilai maka semakin tepat kesimpulan yang diambil","3 hari mungkin terlalu singkat untuk kebiasaan terbentuk; evaluasi terlalu dini bisa salah menyimpulkan"],answer:2,explain:"Menilai sebelum solusi punya kesempatan bekerja menghasilkan kesimpulan yang keliru. Sesuaikan jendela waktu evaluasi dengan jenis solusi.",hint:"Berapa lama biasanya kebiasaan baru butuh untuk 'menempel'?"},
{n:48,type:"mcq",micro:"Menghindari 'evaluasi yang menghukum'",q:"Kalau evaluasi selalu berujung pada mencari siapa yang bersalah, akibatnya...",options:["Orang menghindari mencoba hal baru dan menyembunyikan masalah — evaluasi jadi tidak jujur","Semua orang jadi lebih hati-hati dan hasilnya lebih baik","Tidak ada akibat"],answer:0,explain:"Budaya menyalahkan membunuh kejujuran dan keberanian mencoba. Fokuskan evaluasi pada perbaikan sistem, bukan menghukum individu.",hint:"Apa yang orang lakukan kalau tahu kesalahan pasti dihukum keras?"},
{n:49,type:"mcq",micro:"Solusi yang bekerja karena alasan lain",q:"Solusi 'kotak saran' membuat keluhan menurun. Tapi ternyata karena guru jadi lebih sering berkeliling (bukan karena kotaknya). Evaluasi yang teliti...",options:["Tidak peduli apa penyebabnya, selama keluhan menurun maka kotak saran dianggap sudah berhasil sepenuhnya","Menyelidiki MENGAPA hasil membaik, agar kita tahu bagian mana yang benar-benar berperan","Cukup melihat hasilnya yang membaik saja, karena mencari sebab hanya akan menambah pekerjaan yang tidak perlu"],answer:1,explain:"Memahami mekanisme keberhasilan penting: kita ingin mempertahankan bagian yang benar-benar bekerja, bukan yang kebetulan.",hint:"Kalau kita hapus kotaknya tapi guru tetap berkeliling, apakah hasil tetap baik?"},
{n:50,type:"mcq",micro:"Menetapkan pemilik evaluasi",q:"Agar evaluasi benar-benar dilakukan (tidak terlupa setelah solusi jalan), sebaiknya...",options:["Berharap saja ada seseorang yang akan ingat untuk mengevaluasi nanti, karena solusi yang baik pasti diingat","Evaluasi akan terjadi dengan sendirinya setelah solusi berjalan beberapa waktu tanpa perlu ditugaskan ke siapa pun","Ada orang & tanggal yang ditetapkan: 'Rina akan mengevaluasi pada tanggal X dengan data Y'"],answer:2,explain:"Evaluasi yang tidak dijadwalkan dan tidak ada pemiliknya sering tidak pernah terjadi.",hint:"Siapa dan kapan?"},
{n:51,type:"open",micro:"Merancang rencana evaluasi lengkap",q:"Solusi: 'sistem tutor sebaya' untuk masalah 'banyak siswa tertinggal di matematika'. Rancang rencana evaluasi: (1) ukuran keberhasilan (min. 2), (2) baseline, (3) jadwal evaluasi (formatif & sumatif), (4) sumber data, (5) ambang 'cukup berhasil', (6) siapa mengevaluasi.",explain:"Jawaban baik menyebut ukuran relevan, baseline, evaluasi bertahap, sumber data campuran, ambang jelas, dan pemilik.",hint:"Pastikan salah satu ukuran menangkap 'apakah ada yang dirugikan' (misalnya nilai tutor sendiri).",sample:"(1) Ukuran: rata-rata nilai kuis matematika bulanan siswa yang ikut tutor; jumlah siswa di bawah KKM; tingkat kehadiran & kepuasan sesi tutor. (2) Baseline: rata-rata & jumlah di bawah KKM dari 2 kuis sebelum program. (3) Formatif: cek tiap 2 minggu — kehadiran sesi, umpan balik singkat tutor & tutee; Sumatif: setelah 8 minggu — bandingkan nilai & jumlah di bawah KKM. (4) Data: nilai kuis, daftar hadir sesi, kuesioner 5 pertanyaan, wawancara singkat 4 siswa. (5) Ambang: rata-rata naik ≥ 10 poin DAN jumlah di bawah KKM turun ≥ 40%, tanpa penurunan pada siswa tutor sendiri. (6) Pengevaluasi: ketua kelas + guru matematika, data dikumpulkan bergiliran oleh 2 siswa."},
{n:52,type:"mcq",micro:"Refleksi individu",q:"Setelah menyelesaikan masalah sendiri, pertanyaan refleksi yang membangun keterampilan:",options:["'Strategi apa yang berhasil? Di mana aku terjebak dan bagaimana keluar? Apa yang akan kucoba lebih dulu lain kali?'","'Kenapa masalah ini bisa ada di dunia, dan sejak kapan masalah seperti ini mulai muncul pertama kali?'","'Siapa yang bisa kusalahkan atas kesulitan tadi, supaya orang itu tidak mengulangi kesalahannya lagi?'"],answer:0,explain:"Refleksi yang fokus pada proses dan strategi mentransfer pelajaran ke masalah berikutnya.",hint:"Apa yang bisa kamu bawa ke masalah selanjutnya?"},
{n:53,type:"tf",micro:"Evaluasi bisa mengubah definisi masalah",q:"Benar atau Salah: Setelah solusi dijalankan dan dievaluasi, definisi masalah awal tidak boleh diubah lagi apa pun temuannya.",answer:false,explain:"Kadang evaluasi mengungkap bahwa masalah aslinya tidak dirumuskan dengan tepat ('solusi bekerja tapi orang tetap tidak puas'), dan langkah yang benar adalah kembali mendefinisikan masalah.",hint:"Kalau solusi berhasil tapi keluhan tetap, apa yang mungkin salah?"},
{n:54,type:"mcq",micro:"Membandingkan dengan biaya melakukan-tidak-melakukan",q:"Solusi menghabiskan Rp200.000 dan mengurangi masalah 30%. Evaluasi nilai-untuk-uang mempertanyakan...",options:["Hanya berapa banyak uang yang dihabiskan oleh solusi itu, tanpa membandingkannya dengan hasil yang didapat","Apakah Rp200.000 itu sepadan dengan pengurangan 30%, dan adakah solusi lain yang memberi hasil serupa lebih murah","Hanya apakah masalahnya berkurang atau tidak, tanpa mempertimbangkan berapa biaya yang harus dikeluarkan"],answer:1,explain:"Evaluasi lengkap menimbang hasil terhadap biaya, dan membandingkan dengan alternatif.",hint:"Apakah hasil yang sama bisa dicapai dengan Rp50.000?"},
{n:55,type:"mcq",micro:"Data yang tidak lengkap",q:"Kamu hanya sempat mengumpulkan sedikit data dan hasilnya ambigu. Kesimpulan evaluasi yang jujur:",options:["'Berhasil' — karena ingin cepat selesai dan data yang sedikit itu sudah terlihat cukup menjanjikan bagi tim","'Gagal' — karena datanya sedikit dan hasilnya tidak jelas, sehingga solusinya pasti tidak akan pernah berguna","'Belum bisa disimpulkan; perlu data lebih / waktu lebih sebelum memutuskan lanjut atau ganti'"],answer:2,explain:"Mengakui ketidakpastian lebih baik daripada memaksakan kesimpulan dari bukti yang lemah.",hint:"Apa jawaban jujur kalau datanya belum cukup?"},
{n:56,type:"mcq",micro:"Menstandarkan solusi yang berhasil",q:"Solusi terbukti berhasil setelah evaluasi. Langkah agar manfaatnya bertahan:",options:["Jadikan prosedur tetap / checklist, latih orang yang menjalankan, dan jadwalkan tinjauan berkala","Anggap selesai dan lupakan","Rahasiakan caranya"],answer:0,explain:"Solusi yang berhasil perlu 'dilembagakan' agar tidak bergantung pada satu orang dan tidak memudar.",hint:"Bagaimana memastikan solusi tetap berjalan setelah kamu tidak lagi mengawasinya?"},
{n:57,type:"tf",micro:"Merayakan keberhasilan itu berguna",q:"Benar atau Salah: Mengakui dan merayakan solusi yang berhasil (sekecil apa pun) membantu tim tetap bersemangat menghadapi masalah berikutnya.",answer:true,explain:"Pengakuan atas keberhasilan membangun keyakinan dan energi. Refleksi tidak harus selalu tentang kekurangan.",hint:"Apa efek dari selalu fokus pada yang kurang, tanpa pernah mengakui yang berhasil?"},
{n:58,type:"mcq",micro:"Evaluasi yang mengubah kriteria di tengah jalan",q:"Solusi tidak memenuhi kriteria awal, lalu seseorang usul 'turunkan saja kriterianya biar terlihat berhasil'. Ini...",options:["Selalu boleh","Menipu diri sendiri; kalau kriteria memang terlalu ketat, itu diskusi tersendiri, tapi jangan mengubahnya hanya agar hasil terlihat baik","Cara pintar untuk sukses"],answer:1,explain:"Mengubah target agar cocok dengan hasil menghilangkan gunanya evaluasi. Kriteria bisa ditinjau, tapi dengan alasan jujur, bukan untuk 'menang'.",hint:"Apa gunanya target kalau digeser tiap kali tidak tercapai?"},
{n:59,type:"mcq",micro:"Pelajaran yang bisa ditransfer",q:"Pelajaran evaluasi yang paling berharga untuk masa depan biasanya berupa...",options:["Daftar lengkap semua hal yang salah selama minggu ini, lengkap dengan nama orang-orang yang membuat kesalahan itu pada masalah yang sedang dihadapi","Rincian detail kejadian pada masalah ini saja, seperti jam, tempat, dan nama orangnya, yang tidak berlaku pada masalah lain di masa depan","Prinsip umum ('perkirakan waktu × 1,5', 'uji di kelompok kecil dulu') yang berlaku di banyak masalah, bukan hanya detail masalah ini"],answer:2,explain:"Pelajaran berupa prinsip bisa dipakai lagi; pelajaran berupa detail spesifik jarang berguna untuk masalah lain.",hint:"Mana yang berguna untuk proyek berikutnya: 'kertas biru habis' atau 'selalu cek stok bahan seminggu sebelum tenggat'?"},
{n:60,type:"open",micro:"Refleksi terstruktur",q:"Pilih satu masalah yang pernah kamu selesaikan (atau coba selesaikan). Lakukan refleksi terstruktur: (1) apa hasilnya vs yang diharapkan, (2) apa yang berjalan baik dalam prosesmu, (3) di mana kamu terjebak & bagaimana keluar (atau tidak), (4) satu kesalahan & pelajarannya, (5) dua prinsip yang akan kamu bawa ke masalah berikutnya.",explain:"Jawaban baik: membandingkan hasil vs harapan, menyebut kekuatan proses, titik macet & responsnya, satu kesalahan konkret + pelajaran, dan prinsip yang bisa ditransfer.",hint:"Bagian (5) harus berupa prinsip umum, bukan detail spesifik masalah itu.",sample:"Contoh — Masalah: menyiapkan lomba cerdas cermat antar kelompok. (1) Acara berjalan tapi molor 40 menit dari jadwal; peserta puas, panitia kelelahan. (2) Pembagian tugas per bidang jelas; soal disiapkan jauh hari. (3) Terjebak saat alat pengeras suara error 10 menit sebelum mulai — keluar dengan pinjam dari kelas sebelah, tapi kehilangan waktu. (4) Kesalahan: tidak menguji semua alat H-1. Pelajaran: buat checklist alat & uji semuanya sehari sebelumnya. (5) Prinsip: (a) uji semua peralatan minimal 1 hari sebelum acara; (b) tambahkan penyangga waktu 20% ke setiap jadwal acara."},
{n:61,type:"mcq",micro:"Bias 'sudah terlanjur'",q:"Tim sudah menghabiskan banyak waktu pada solusi yang jelas tidak berhasil, tapi enggan berhenti 'karena sudah sejauh ini'. Ini bias biaya hangus. Penalaran yang benar:",options:["Waktu yang sudah dihabiskan tidak bisa kembali; keputusan sekarang harus berdasarkan 'apa langkah terbaik dari sini', bukan 'sudah berapa banyak yang dikeluarkan'","Teruskan saja solusinya karena sudah banyak waktu dan usaha yang dihabiskan, sayang sekali kalau dihentikan begitu saja pada saat ini","Mulai lagi dari nol setiap kali ada kegagalan kecil, tanpa pernah mempertimbangkan apa yang sudah dipelajari dari percobaan sebelumnya oleh tim"],answer:0,explain:"Biaya hangus tidak relevan untuk keputusan ke depan. Yang penting: dari titik ini, apa pilihan terbaik?",hint:"Apakah 'sudah keluar banyak' alasan yang baik untuk terus mengeluarkan lebih banyak?"},
{n:62,type:"mcq",micro:"Mengukur yang mudah, bukan yang penting",q:"Tim mengevaluasi 'kampanye membaca' dengan menghitung poster yang dipasang (mudah dihitung) alih-alih perubahan kebiasaan membaca (yang penting). Kelemahan:",options:["Tidak ada kelemahan","Mengukur aktivitas, bukan hasil — banyak poster tidak berarti orang jadi lebih banyak membaca","Poster memang ukuran terbaik"],answer:1,explain:"Godaan umum: mengukur apa yang mudah, bukan apa yang penting. Pastikan ukuran mencerminkan tujuan sebenarnya.",hint:"Apakah 'jumlah poster' sama dengan 'orang membaca lebih banyak'?"},
{n:63,type:"tf",micro:"Ukuran bisa mendistorsi perilaku",q:"Benar atau Salah: Kalau sebuah ukuran dijadikan target yang dikejar mati-matian, orang bisa mulai 'mengejar angkanya' dengan cara yang tidak sesuai tujuan aslinya.",answer:true,explain:"Contoh: kalau 'jumlah buku dipinjam' jadi target, orang bisa meminjam buku tanpa membacanya. Ukuran perlu dipilih dan dipakai hati-hati.",hint:"Apa yang terjadi kalau kelas dinilai dari 'jumlah tangan terangkat' bukan 'kualitas pertanyaan'?"},
{n:64,type:"mcq",micro:"Kapan berhenti mengiterasi",q:"Kamu sudah memperbaiki solusi 4 kali; tiap perbaikan hanya menambah sedikit. Tanda untuk berhenti mengiterasi:",options:["Tidak pernah berhenti memperbaiki, karena solusi yang baik harus terus diubah sampai benar-benar sempurna","Berhenti saja setelah percobaan pertama, sebab perbaikan kedua dan seterusnya pasti hanya membuang waktu","Perbaikan tambahan sudah kecil dan tidak sepadan dengan usahanya, sementara solusi sudah memenuhi kriteria 'cukup baik'"],answer:2,explain:"Iterasi punya hasil yang makin berkurang. Berhenti saat 'cukup baik' tercapai dan perbaikan lanjutan tidak sepadan.",hint:"Kapan usaha memperbaiki lebih besar daripada manfaat perbaikannya?"},
{n:65,type:"mcq",micro:"Evaluasi yang mengabaikan pihak yang tidak bersuara",q:"Evaluasi solusi 'jam belajar tambahan sore' hanya menanyai siswa yang hadir. Yang terlewat:",options:["Siswa yang TIDAK bisa hadir (mungkin karena solusi ini tidak cocok untuk mereka) tidak terdengar suaranya","Tidak ada yang terlewat, karena siswa yang mau menjawab sudah cukup mewakili semua pendapat tentang solusi","Siswa yang hadir sudah mewakili semua siswa lain, sehingga suara yang tidak hadir tidak perlu dicari lagi"],answer:0,explain:"Mengevaluasi hanya dengan orang yang 'berhasil' memakai solusi menyembunyikan mereka yang tersisih.",hint:"Siapa yang justru tidak bisa memberi umpan balik karena solusi ini tidak menjangkau mereka?"},
{n:66,type:"tf",micro:"Hasil nol bukan berarti tidak belajar apa-apa",q:"Benar atau Salah: Kalau sebuah solusi tidak memperbaiki masalah sama sekali, maka seluruh usaha itu sia-sia dan tidak menghasilkan pelajaran apa pun.",answer:false,explain:"'Kami mencoba X dan tidak ada perubahan' menunjukkan X mungkin bukan faktor pentingnya — informasi berharga yang menyempit pencarian berikutnya.",hint:"Apakah eksperimen yang 'gagal' mengajarkan sesuatu kepada ilmuwan?"},
{n:67,type:"mcq",micro:"Terlalu cepat menyatakan menang",q:"Solusi baru berjalan 3 hari dengan hasil bagus, lalu diumumkan 'berhasil total' dan semua perhatian pindah ke hal lain. Risiko:",options:["Tiga hari selalu cukup","Hasil awal bisa karena kebaruan atau kebetulan; tanpa pemantauan lanjutan, kemunduran bisa tidak ketahuan","Tidak ada risiko"],answer:1,explain:"Menyatakan menang terlalu dini dan menghentikan pemantauan bisa membuat kemunduran terlambat disadari.",hint:"Apakah 3 hari cukup untuk yakin sesuatu bertahan?"},
{n:68,type:"mcq",micro:"Evaluasi yang mencari pembenaran",q:"Perbedaan antara 'mengevaluasi untuk belajar' dan 'mengevaluasi untuk membenarkan keputusan yang sudah dibuat':",options:["Keduanya sama","Yang kedua lebih jujur","Yang pertama terbuka pada temuan apa pun; yang kedua hanya mencari bukti yang mendukung dan mengabaikan sisanya"],answer:2,explain:"Evaluasi yang tujuannya membenarkan bukan evaluasi sungguhan. Masuki evaluasi dengan kesediaan menemukan bahwa kamu salah.",hint:"Apakah kamu benar-benar ingin tahu hasilnya, atau sudah tahu kesimpulan yang kamu mau?"},
{n:69,type:"mcq",micro:"Menimbang bukti yang bertentangan",q:"Data kuantitatif bilang solusi berhasil; umpan balik kualitatif banyak yang negatif. Langkah bijak:",options:["Cari tahu mengapa keduanya berbeda — mungkin solusi memperbaiki angka tapi dengan cara yang membuat orang tidak nyaman; keduanya informasi valid","Percaya angka saja dan abaikan semua komentar yang negatif, karena angka tidak mungkin berbohong sedangkan komentar hanyalah perasaan sesaat","Percaya komentar negatif saja dan abaikan angka yang ada, karena perasaan orang selalu lebih penting daripada data yang telah dikumpulkan"],answer:0,explain:"Ketegangan antara jenis bukti sering menunjuk ke sesuatu penting yang perlu dipahami, bukan salah satu yang harus dibuang.",hint:"Bagaimana bisa 'angka membaik' dan 'orang tidak senang' terjadi bersamaan?"},
{n:70,type:"order",micro:"Menyelidiki mengapa solusi gagal",q:"Urutkan langkah menyelidiki kegagalan sebuah solusi.",items:["Pastikan solusi benar-benar dijalankan sesuai rencana (bukan gagal karena tidak dilaksanakan)","Periksa apakah asumsi di balik solusi ternyata salah","Periksa apakah ada faktor luar yang menggagalkannya","Simpulkan penyebab paling mungkin & apa artinya untuk langkah berikutnya"],answer:[0,1,2,3],explain:"Cek pelaksanaan → cek asumsi → cek faktor luar → simpulkan.",hint:"Solusi bagus yang tidak dijalankan juga akan 'gagal' — periksa itu dulu."},
{n:71,type:"mcq",micro:"Bias 'akhir yang bahagia'",q:"Tim mengingat proyek sebagai 'sukses besar' hanya karena minggu terakhir berjalan lancar, melupakan bulan-bulan kacau sebelumnya. Untuk refleksi yang akurat:",options:["Lupakan saja bagian yang sulit dan kacau, karena yang penting adalah akhir yang menyenangkan untuk diceritakan","Tinjau seluruh garis waktu, bukan hanya bagian akhir yang paling diingat","Ingatan tentang minggu terakhir sudah cukup untuk menilai seluruh proyek, tanpa perlu catatan bulan sebelumnya"],answer:1,explain:"Ingatan cenderung didominasi kejadian akhir. Refleksi berbasis catatan seluruh proyek lebih adil.",hint:"Bagian mana dari proyek yang paling kamu ingat, dan apakah itu mewakili keseluruhannya?"},
{n:72,type:"mcq",micro:"Menghindari perbaikan berlebihan",q:"Setiap kali ada satu keluhan kecil, tim langsung mengubah solusi. Setelah 10 perubahan, solusinya jadi rumit dan membingungkan. Pelajaran:",options:["Jangan pernah mengubah solusi setelah dijalankan, apa pun keluhan yang masuk, sebab setiap perubahan hanya akan membuat semua orang bingung lagi","Ubah solusi setiap kali ada masukan sekecil apa pun dari siapa saja, supaya semua orang merasa pendapatnya selalu langsung dihargai oleh tim","Kumpulkan umpan balik, cari pola, dan lakukan perubahan yang terpertimbangkan secara berkala — bukan bereaksi pada tiap suara satu per satu"],answer:2,explain:"Iterasi yang sehat berdasarkan pola dalam umpan balik, bukan reaksi refleks terhadap setiap komentar.",hint:"Apa yang terjadi pada solusi yang diubah setiap kali ada satu keluhan?"},
{n:73,type:"tf",micro:"Evaluasi butuh sumber daya yang direncanakan",q:"Benar atau Salah: Waktu dan tenaga untuk mengevaluasi sebuah solusi sebaiknya direncanakan dari awal, bukan diharapkan 'muncul sendiri' setelah solusi jalan.",answer:true,explain:"Evaluasi yang tidak dialokasikan sumber dayanya sering tidak terjadi. Masukkan ke rencana sejak awal.",hint:"Apa yang terjadi pada tugas yang tidak ada waktu dan orangnya?"},
{n:74,type:"mcq",micro:"Solusi berhasil di satu tempat, gagal di tempat lain",q:"Solusi yang berhasil di kelas A gagal saat diterapkan di kelas B. Kesimpulan yang tepat:",options:["Selidiki perbedaan konteks (jumlah siswa, kebiasaan, sumber daya) — solusi mungkin perlu disesuaikan, bukan ditolak sepenuhnya","Solusinya buruk","Kelas B yang salah"],answer:0,explain:"Kegagalan transfer sering karena perbedaan konteks. Evaluasi yang baik menanyakan 'apa yang berbeda di sini'.",hint:"Apa yang tidak sama antara kelas A dan kelas B?"},
{n:75,type:"mcq",micro:"Batas ukuran tunggal",q:"Mengevaluasi solusi kompleks hanya dengan satu angka berisiko...",options:["Membuat evaluasi terlalu lengkap","Menyembunyikan efek penting yang tidak tertangkap angka itu (efek samping, keadilan, keberlanjutan)","Selalu akurat"],answer:1,explain:"Solusi yang berdampak luas butuh beberapa ukuran yang menangkap sisi berbeda.",hint:"Bisakah satu angka menangkap 'berhasil, adil, dan bertahan'?"},
{n:76,type:"mcq",micro:"Refleksi tanpa tindakan",q:"Tim rutin melakukan retrospektif tapi tidak pernah mengubah apa pun sebagai hasilnya. Retrospektif menjadi...",options:["Tetap berguna meski tanpa tindakan, karena kegiatan mengobrol bersama saja sudah cukup untuk memperbaiki kerja tim","Lebih baik daripada tidak dilakukan sama sekali, walaupun tidak ada satu pun perubahan yang pernah dijalankan","Ritual kosong; refleksi hanya berguna kalau menghasilkan perubahan konkret yang benar-benar dijalankan"],answer:2,explain:"Nilai refleksi ada pada tindak lanjutnya. Sepakati sedikit perubahan yang benar-benar diterapkan.",hint:"Apa gunanya menemukan pelajaran kalau tidak pernah dipakai?"},
{n:77,type:"tf",micro:"Evaluasi jujur kadang tidak nyaman",q:"Benar atau Salah: Evaluasi yang baik kadang menghasilkan kesimpulan yang tidak kita sukai (solusi favorit kita ternyata tidak berhasil), dan itu tanda evaluasinya jujur.",answer:true,explain:"Kalau evaluasi selalu memberi hasil yang menyenangkan, mungkin ia tidak benar-benar menguji apa pun.",hint:"Apakah evaluasi yang selalu bilang 'kamu benar' bisa dipercaya?"},
{n:78,type:"mcq",micro:"Menggeneralisasi dari satu evaluasi",q:"Satu solusi berhasil sekali. Menyimpulkan 'pendekatan ini selalu terbaik untuk semua masalah serupa' adalah...",options:["Terlalu jauh dari satu kasus; satu keberhasilan adalah bukti awal, bukan aturan umum","Kesimpulan yang tepat","Selalu aman"],answer:0,explain:"Satu titik data mendukung dugaan tapi tidak membuktikan aturan. Butuh beberapa kasus dan pemahaman mengapa ia bekerja.",hint:"Apakah berhasil sekali berarti berhasil selalu?"},
{n:79,type:"mcq",micro:"Menyeimbangkan evaluasi dan tindakan",q:"Menghabiskan lebih banyak waktu mengevaluasi daripada menyelesaikan masalah menunjukkan...",options:["Tidak masalah","Ketidakseimbangan; evaluasi sebaiknya cukup untuk memandu keputusan, bukan menjadi kegiatan utama","Evaluasi memang harus dominan"],answer:1,explain:"Evaluasi melayani pemecahan masalah, bukan sebaliknya. Sesuaikan porsinya.",hint:"Apakah tujuannya menyelesaikan masalah, atau mengevaluasi selamanya?"},
{n:80,type:"open",micro:"Menemukan kelemahan sebuah evaluasi",q:"Sebuah tim melapor: 'Solusi kami berhasil. Kami tanya 8 siswa dan semua bilang suka.' Tuliskan minimal 3 kelemahan evaluasi ini dan bagaimana memperbaikinya.",explain:"Jawaban baik mengenali masalah sampel, ukuran yang salah (kepuasan vs efektivitas), tiadanya baseline & kriteria, dan efek samping yang tidak diperiksa.",hint:"Tanya: sampelnya siapa? ukurannya mengukur apa? ada pembanding? ada yang dirugikan?",sample:"Kelemahan: (1) 8 siswa mungkin bukan sampel yang mewakili — siapa mereka? apakah dipilih acak atau kebetulan yang mendukung? (2) 'suka' bukan ukuran apakah MASALAH ASLINYA teratasi — solusi bisa disukai tanpa efektif; (3) tidak ada data 'sebelum' (baseline) untuk membandingkan; (4) tidak menanyakan efek samping atau pihak yang mungkin dirugikan; (5) tidak ada kriteria keberhasilan yang ditetapkan di awal. Perbaikan: tetapkan ukuran objektif terkait masalah asli (mis. jumlah kejadian), kumpulkan baseline, tanyai sampel acak yang mencakup yang skeptis dan yang tidak memakai solusi, tanyakan kesulitan/kerugian, dan bandingkan dengan ambang yang disepakati."},
{n:81,type:"mcq",micro:"Evaluasi solusi berlapis",q:"Solusi perundungan berlapis (aturan + pendidikan + dukungan korban). Kalau kasus menurun, cara mengetahui bagian mana yang berperan:",options:["Hapus bagian satu per satu untuk melihat efeknya","Tidak perlu tahu","Sulit dipastikan tepat, tapi bisa didekati: perhatikan waktu tiap bagian mulai, tanyakan siswa apa yang mereka rasa paling berpengaruh, dan pertahankan semua bagian yang tidak mahal"],answer:2,explain:"Untuk solusi berlapis, memisahkan kontribusi tiap bagian sulit; pendekatan praktis menggabungkan bukti waktu, persepsi, dan mempertahankan bagian berbiaya rendah.",hint:"Bisakah kita yakin bagian mana yang bekerja tanpa menghapus yang mungkin membantu?"},
{n:82,type:"mcq",micro:"Evaluasi ketika hasilnya butuh waktu lama",q:"Solusi 'program membaca' mungkin baru terlihat dampaknya pada nilai setahun kemudian. Sementara itu, evaluasi formatif bisa memakai...",options:["Indikator antara: jumlah buku dibaca, waktu membaca mandiri, sikap terhadap membaca — yang bisa diukur lebih cepat","Menunggu setahun tanpa memeriksa apa pun","Membatalkan program"],answer:0,explain:"Untuk hasil jangka panjang, indikator antara (leading indicators) memberi sinyal awal apakah solusi berada di jalur yang benar.",hint:"Apa tanda-tanda awal bahwa program membaca 'bekerja' sebelum nilai berubah?"},
{n:83,type:"tf",micro:"Evaluasi bagian dari siklus, bukan akhir",q:"Benar atau Salah: Evaluasi selalu merupakan langkah terakhir dalam pemecahan masalah dan tidak pernah membawa kita kembali ke langkah sebelumnya.",answer:false,explain:"Pemecahan masalah adalah siklus. Evaluasi sering membawa kita kembali — mendefinisikan ulang masalah, menghasilkan ide baru, merevisi rencana — membuka putaran berikutnya yang lebih terinformasi.",hint:"Apa yang terjadi setelah evaluasi menunjukkan solusi belum cukup?"},
{n:84,type:"mcq",micro:"Menetapkan kriteria untuk masalah yang nilainya beragam",q:"Untuk 'membuat kegiatan sekolah lebih inklusif', kriteria evaluasi sebaiknya melibatkan...",options:["Satu angka kehadiran saja, karena banyaknya yang hadir sudah cukup menunjukkan bahwa kegiatan itu inklusif","Masukan dari beragam kelompok siswa tentang apa arti 'inklusif' bagi mereka, agar ukuran mencerminkan pengalaman yang beragam","Hanya pendapat panitia saja, karena merekalah yang paling tahu apa yang sudah dikerjakan pada kegiatan itu"],answer:1,explain:"Untuk masalah yang menyangkut pengalaman beragam orang, kriteria yang ditetapkan sepihak berisiko melewatkan hal yang penting bagi sebagian kelompok.",hint:"Siapa yang harus ikut menentukan seperti apa 'berhasil' itu?"},
{n:85,type:"order",micro:"Siklus lengkap: dari evaluasi ke perbaikan",q:"Urutkan langkah dari 'solusi sudah berjalan sebulan' sampai 'putaran perbaikan berikutnya dimulai'.",items:["Kumpulkan bukti terhadap kriteria & baseline (kuantitatif + kualitatif)","Simpulkan: memenuhi kriteria? efek samping? untuk siapa berhasil/tidak?","Refleksikan proses: apa yang perlu diubah dalam CARA kita bekerja","Putuskan tindakan (lanjut/perbaiki/ganti/definisikan ulang) & rencanakan putaran berikutnya"],answer:[0,1,2,3],explain:"Kumpulkan bukti → simpulkan hasil → refleksikan proses → putuskan & rencanakan lagi.",hint:"Bukti dulu, kesimpulan hasil, lalu refleksi proses, baru keputusan."},
{n:86,type:"mcq",micro:"Evaluasi yang memperhitungkan siapa diuntungkan",q:"Solusi menaikkan rata-rata nilai kelas, tapi setelah diperiksa, kenaikan hampir semuanya dari siswa yang sudah pandai; yang tertinggal tidak terbantu. Evaluasi jujur menyimpulkan...",options:["Berhasil, rata-rata naik","Gagal total","Solusi 'berhasil' pada rata-rata tapi TIDAK menyelesaikan masalah aslinya (membantu yang tertinggal); perlu disesuaikan"],answer:2,explain:"Ukuran agregat (rata-rata) bisa menyembunyikan bahwa solusi tidak menjangkau kelompok yang jadi tujuan awal.",hint:"Masalah aslinya tentang siapa, dan apakah mereka terbantu?"},
{n:87,type:"tf",micro:"Dokumentasi evaluasi bernilai lintas waktu",q:"Benar atau Salah: Mencatat hasil evaluasi hanya berguna selama proyek berjalan; setelah selesai, catatan itu tidak ada nilainya bagi siapa pun.",answer:false,explain:"Catatan evaluasi yang rapi (apa yang dicoba, hasilnya, mengapa) justru berharga bertahun-tahun kemudian — tanpanya, tiap generasi mengulang percobaan yang sama.",hint:"Bagaimana panitia 3 tahun lagi tahu bahwa ide X sudah dicoba dan gagal karena Y?"},
{n:88,type:"mcq",micro:"Menyeimbangkan bukti dan kecepatan",q:"Keputusan mendesak, bukti belum lengkap. Pendekatan yang masuk akal:",options:["Buat keputusan terbaik dengan bukti yang ada, tapi TANDAI sebagai sementara dan jadwalkan evaluasi ulang saat bukti lebih lengkap","Tunda keputusan sampai bukti menjadi sempurna dan lengkap, walaupun keadaan mendesak dan waktu sudah hampir habis","Putuskan sekarang lalu jangan pernah ditinjau ulang, supaya orang lain yakin bahwa tim tidak pernah ragu"],answer:0,explain:"Untuk keputusan mendesak, 'putuskan sekarang, tinjau nanti' sering lebih baik daripada lumpuh menunggu kepastian.",hint:"Bisakah sebuah keputusan bersifat 'sementara sampai kita tahu lebih banyak'?"},
{n:89,type:"mcq",micro:"Evaluasi solusi yang tak bisa dibandingkan langsung",q:"Kamu tidak bisa menjalankan 'dengan solusi' dan 'tanpa solusi' bersamaan pada kelas yang sama. Cara mendekati:",options:["Klaim saja bahwa solusi itu berhasil tanpa membandingkan apa pun, karena hasilnya pasti terlihat dari perasaan","Bandingkan dengan periode sebelumnya (asal faktor lain relatif sama), atau dengan kelas serupa, sambil menyadari keterbatasannya","Menyerah saja dan menganggap solusi tidak bisa dievaluasi, karena tidak ada kelas pembanding pada waktu yang sama"],answer:1,explain:"Evaluasi dunia nyata jarang sempurna. Perbandingan yang tidak ideal tetap berguna asal keterbatasannya diakui.",hint:"Apa pembanding terbaik yang tersedia, meski tidak sempurna?"},
{n:90,type:"mcq",micro:"Refleksi tim yang menghasilkan sistem",q:"Setelah beberapa proyek, tim menyadari selalu terlambat karena estimasi optimis. Perbaikan tingkat sistem:",options:["Berjanji akan lebih hati-hati","Abaikan polanya","Buat aturan tim: 'kalikan semua estimasi awal dengan 1,5' dan 'tambahkan minggu penyangga', lalu terapkan di proyek berikutnya"],answer:2,explain:"Refleksi yang kuat mengubah pola berulang menjadi aturan/kebiasaan tim, bukan sekadar niat.",hint:"Bagaimana mengubah 'kami selalu meleset optimis' menjadi tindakan yang otomatis?"},
{n:91,type:"mcq",micro:"Evaluasi dan akuntabilitas yang adil",q:"Sebuah solusi gagal terutama karena faktor di luar kendali tim (dana dipotong mendadak). Refleksi yang adil...",options:["Membedakan apa yang dalam kendali tim (yang bisa dipelajari & diperbaiki) dari yang di luar kendali (yang perlu diantisipasi dengan kontinjensi lain kali)","Menyalahkan tim atas segalanya, termasuk hal yang sama sekali tidak bisa mereka kendalikan, supaya mereka lebih berhati-hati pada proyek berikutnya","Menyalahkan semuanya pada faktor luar saja, sehingga tim tidak perlu belajar apa pun dari kegagalan itu dan tidak perlu menyiapkan cadangan lagi"],answer:0,explain:"Refleksi yang berguna memisahkan pelajaran yang bisa ditindaklanjuti dari kejadian di luar kendali — sambil menanyakan apakah kontinjensi bisa lebih baik.",hint:"Apa yang bisa tim ubah, dan apa yang hanya bisa diantisipasi?"},
{n:92,type:"tf",micro:"Evaluasi & refleksi adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Kemampuan mengevaluasi solusi secara jujur dan merefleksikan proses dengan berguna berkembang dengan latihan dan dengan lingkungan yang aman untuk mengakui kesalahan.",answer:true,explain:"Seperti keterampilan pemecahan masalah lainnya, evaluasi & refleksi menajam dengan pengulangan dan budaya yang mendukung kejujuran.",hint:"Apakah orang menjadi lebih baik dalam merefleksikan setelah sering berlatih?"},
{n:93,type:"mcq",micro:"Menutup dengan pengakuan kontribusi",q:"Bagian penutupan yang sering terlupa tapi penting:",options:["Langsung pindah ke masalah berikutnya tanpa menoleh ke belakang, karena mengakui kontribusi hanya membuang waktu","Mengakui kontribusi tiap orang secara spesifik dan berbagi kredit — ini menjaga motivasi untuk masalah berikutnya","Hanya menyoroti kesalahan masing-masing orang, supaya semua anggota lebih teliti ketika mengerjakan proyek berikutnya"],answer:1,explain:"Pengakuan yang tulus atas usaha orang adalah bagian dari refleksi yang sehat dan membangun tim yang tahan lama.",hint:"Apa efek jangka panjang dari selalu mengakhiri proyek dengan daftar kesalahan tanpa pengakuan?"},
{n:94,type:"open",micro:"Evaluasi & refleksi untuk masalah nyata",q:"Pilih solusi yang sedang/sudah kamu jalankan untuk masalah nyata. Buat 'laporan evaluasi & refleksi': (1) masalah, tujuan, kriteria, baseline, (2) bukti yang dikumpulkan (kuantitatif & kualitatif) + keterbatasannya, (3) kesimpulan hasil: untuk siapa berhasil/tidak, efek samping, (4) keputusan: lanjut/perbaiki/ganti/definisikan ulang + alasan, (5) refleksi proses: 2 hal yang berjalan baik, 2 yang perlu diubah, (6) 2 prinsip yang akan kamu bawa ke masalah berikutnya.",explain:"Kapstone-lite: menghasilkan artefak evaluasi lengkap yang memilah hasil per kelompok, mengakui keterbatasan bukti, dan menghasilkan prinsip yang bisa ditransfer.",hint:"Bagian (6) harus prinsip umum yang berlaku di banyak masalah, bukan detail masalah ini.",sample:"Laporan yang baik mengisi keenam bagian dengan: kriteria & baseline yang nyata (angka), bukti campuran dengan pengakuan jujur atas keterbatasan sampel/pengukuran, kesimpulan yang memilah kelompok yang terbantu dan tidak serta menyebut efek samping, keputusan yang jelas dan beralasan (bukan 'pokoknya lanjut'), refleksi proses yang seimbang (kekuatan + perbaikan), dan prinsip transfer yang berupa aturan umum ('uji peralatan H-1', 'kumpulkan baseline sebelum mulai apa pun'). Contoh domain: solusi 'sudut tenang di kelas untuk yang butuh fokus' — kriteria: keluhan kebisingan turun & sudut dipakai ≥ 3x/hari; baseline: rata-rata 4 keluhan/hari; bukti: hitungan keluhan + pengamatan pemakaian + tanya 6 siswa; dst."},
{n:95,type:"mcq",micro:"Evaluasi mengungkap solusi menciptakan ketergantungan",q:"Solusi 'guru selalu mengingatkan tiap langkah' membuat tugas selesai, tapi evaluasi menunjukkan siswa jadi tidak bisa mulai tanpa diingatkan. Kesimpulan:",options:["Solusi sempurna","Kemandirian tidak penting","Solusi 'berhasil' pada hasil jangka pendek tapi merugikan tujuan yang lebih besar (kemandirian); perlu solusi yang secara bertahap mengurangi bantuan"],answer:2,explain:"Evaluasi yang melihat jauh menanyakan apakah solusi membangun kapasitas atau justru menciptakan ketergantungan.",hint:"Apa yang terjadi kalau bantuan itu dihentikan?"},
{n:96,type:"mcq",micro:"Menghubungkan evaluasi ke keputusan sumber daya",q:"Setelah dievaluasi, solusi terbukti efektif tapi butuh 2 jam kerja relawan tiap minggu tanpa henti. Refleksi yang matang menanyakan...",options:["Apakah beban itu berkelanjutan; bisakah diotomatiskan, dibagi lebih luas, atau dikurangi tanpa kehilangan manfaat inti","Abaikan saja bebannya karena hasilnya sudah bagus, dan relawan pasti selalu bersedia bekerja tanpa batas waktu","Hentikan saja solusi yang sudah terbukti efektif itu, karena solusi yang membutuhkan kerja tiap minggu tidak layak"],answer:0,explain:"Solusi yang efektif tapi membebani segelintir orang terus-menerus berisiko runtuh. Evaluasi keberlanjutan sama pentingnya dengan efektivitas.",hint:"Apa yang terjadi pada solusi setelah relawannya kelelahan?"},
{n:97,type:"tf",micro:"Tujuan akhir evaluasi adalah keputusan yang lebih baik",q:"Benar atau Salah: Evaluasi dan refleksi bernilai bukan karena menghasilkan laporan, melainkan karena menghasilkan keputusan dan tindakan yang lebih baik untuk ke depan.",answer:true,explain:"Laporan yang tidak mengubah keputusan atau perilaku adalah usaha yang sia-sia. Ukur nilai evaluasi dari perubahan yang ia hasilkan.",hint:"Apa gunanya evaluasi yang tidak mengubah apa pun?"},
{n:98,type:"mcq",micro:"Menutup siklus pemecahan masalah",q:"Rangkaian lengkap pemecahan masalah adalah: mengenali & mendefinisikan → memecah → strategi & rencana → menghasilkan & memilih solusi → melaksanakan → mengevaluasi & refleksi → (sering) kembali ke awal dengan pemahaman lebih baik. Ini menunjukkan pemecahan masalah adalah...",options:["Kegiatan yang tidak berpola sama sekali, sehingga urutan langkahnya boleh diacak sesuka hati siapa saja","Sebuah siklus yang berputar dan meningkat, bukan garis lurus sekali jalan","Selalu selesai dalam satu putaran saja, sehingga setelah evaluasi tidak perlu lagi mengulang langkah apa pun"],answer:1,explain:"Evaluasi menghubungkan akhir satu putaran ke awal putaran berikutnya yang lebih terinformasi — spiral, bukan lingkaran datar atau garis lurus.",hint:"Apa yang terjadi setelah evaluasi selesai, untuk masalah yang belum tuntas?"},
{n:99,type:"mcq",micro:"Ringkasan: mengevaluasi & merefleksi",q:"Rangkuman paling tepat:",options:["Rasakan saja apakah solusinya berhasil atau tidak, karena perasaan kelompok sudah cukup menjadi bukti keberhasilan, lalu umumkan hasilnya, anggap semua selesai, dan tidak perlu mencatat pelajaran ataupun memeriksa efek samping dan keberlanjutannya","Umumkan bahwa solusi itu berhasil lalu berhenti di situ, tanpa membandingkannya dengan kriteria dan keadaan sebelumnya, tanpa menanyakan siapa yang terbantu dan siapa yang tidak, dan tanpa merenungkan apa yang bisa dipelajari untuk masalah berikutnya","Bandingkan hasil dengan kriteria & baseline pakai bukti jujur (kuantitatif + kualitatif); periksa untuk siapa berhasil, efek samping, dan keberlanjutan; putuskan lanjut/perbaiki/ganti/definisikan ulang; refleksikan proses menjadi prinsip; catat pelajaran"],answer:2,explain:"Evaluasi = hasil vs kriteria dengan bukti jujur, memilah dampak, memutuskan langkah berikutnya. Refleksi = mengubah pengalaman proses menjadi prinsip yang bisa dipakai lagi.",hint:"Gabungkan: bukti jujur vs kriteria → pilah dampak → putuskan → prinsip → catat."},
{n:100,type:"open",micro:"Kapstone: siklus penuh dengan refleksi",q:"Ambil satu masalah yang kamu jalani dari awal sampai ada solusi yang berjalan. Tuliskan ringkasan seluruh siklus: (1) masalah & bagaimana kamu mendefinisikannya, (2) bagaimana kamu memecah & merencanakannya, (3) solusi yang dipilih & mengapa, (4) apa yang terjadi saat pelaksanaan, (5) hasil evaluasi terhadap kriteria (dengan bukti), (6) keputusan berikutnya, (7) 3 pelajaran — satu tentang masalah itu, satu tentang strategi, satu tentang kerja sama/proses.",explain:"Kapstone menyatukan seluruh domain Pemecahan Masalah: mendefinisikan, memecah, merencanakan, memilih, melaksanakan, mengevaluasi, dan merefleksi menjadi satu narasi yang jujur dan menghasilkan pelajaran bertingkat.",hint:"Ceritakan apa adanya — termasuk bagian yang tidak berjalan mulus; itu justru sumber pelajaran terbaik.",sample:"Ringkasan yang baik menunjukkan seluruh perjalanan dengan jujur: definisi masalah yang mungkin berubah di tengah jalan; rencana yang disesuaikan; solusi yang dipilih dengan alasan (kriteria); pelaksanaan termasuk hambatan nyata dan bagaimana ditangani; evaluasi dengan bukti konkret terhadap kriteria yang ditetapkan, memilah untuk siapa berhasil dan efek samping; keputusan berikutnya yang beralasan (lanjut/perbaiki/dll.); dan tiga pelajaran pada tingkat berbeda — spesifik masalah ('ternyata penyebab utamanya X'), strategi ('menyederhanakan dulu sangat membantu di sini'), dan proses ('pembagian tugas perlu satu pemantau, bukan hanya pelaksana'). Panjang wajar: 200–350 kata."},
];
